PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, student TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'student',banned_until INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id),csrf TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY,seller INTEGER REFERENCES users(id),title TEXT NOT NULL,description TEXT NOT NULL,category TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>0),condition TEXT NOT NULL,status TEXT NOT NULL, frozen INTEGER NOT NULL DEFAULT 0,image TEXT NOT NULL DEFAULT '',reason TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY,product INTEGER REFERENCES products(id),buyer INTEGER REFERENCES users(id),seller INTEGER REFERENCES users(id),title TEXT NOT NULL,price INTEGER NOT NULL,status TEXT NOT NULL, buyer_confirm INTEGER NOT NULL DEFAULT 0,seller_confirm INTEGER NOT NULL DEFAULT 0,place TEXT NOT NULL DEFAULT '',meeting TEXT NOT NULL DEFAULT '',note TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL,completed INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_order ON orders(product) WHERE status IN ('待接单','待交付','争议处理中');
CREATE TABLE IF NOT EXISTS favorites(user_id INTEGER REFERENCES users(id),product INTEGER REFERENCES products(id),PRIMARY KEY(user_id,product));
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,product INTEGER REFERENCES products(id),sender INTEGER REFERENCES users(id),receiver INTEGER REFERENCES users(id),body TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS reviews(id INTEGER PRIMARY KEY,order_id INTEGER REFERENCES orders(id),author INTEGER REFERENCES users(id),rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),body TEXT NOT NULL,updated INTEGER NOT NULL,UNIQUE(order_id,author));
CREATE TABLE IF NOT EXISTS review_history(id INTEGER PRIMARY KEY,review_id INTEGER REFERENCES reviews(id),rating INTEGER,body TEXT,created INTEGER);
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY,author INTEGER REFERENCES users(id),product INTEGER REFERENCES products(id),body TEXT NOT NULL,status TEXT NOT NULL DEFAULT '待处理',result TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL,UNIQUE(author,product));
CREATE TABLE IF NOT EXISTS withdrawals(id INTEGER PRIMARY KEY,order_id INTEGER REFERENCES orders(id),author INTEGER REFERENCES users(id),body TEXT NOT NULL,status TEXT NOT NULL DEFAULT '待审核',result TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_pending_withdrawal ON withdrawals(order_id) WHERE status='待审核';
CREATE TABLE IF NOT EXISTS notices(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),body TEXT NOT NULL,seen INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,actor INTEGER REFERENCES users(id),action TEXT NOT NULL,target INTEGER,detail TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS confirmation_history(id INTEGER PRIMARY KEY,order_id INTEGER REFERENCES orders(id),user_id INTEGER REFERENCES users(id),confirmed INTEGER NOT NULL,revoked INTEGER NOT NULL,reason TEXT NOT NULL);
